(()=>{if(!('serviceWorker'in navigator))return;navigator.serviceWorker.register('./sw.js').catch(()=>{});let installPrompt;const box=document.createElement('div');box.className='install-box';const button=document.createElement('button');button.className='install-app';button.textContent='＋ INSTALAR STREET BRASA';box.append(button);document.body.append(box);if(matchMedia('(display-mode: standalone)').matches||navigator.standalone)box.remove();window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});window.addEventListener('appinstalled',()=>box.remove());button.onclick=async()=>{if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null}else{const dialog=document.createElement('dialog');dialog.innerHTML='<h2>Street Brasa no celular</h2><p>No Android, abra o menu do navegador e escolha “Instalar aplicativo” ou “Adicionar à tela inicial”.</p><p>No iPhone, abra no Safari, toque em Compartilhar e depois em “Adicionar à Tela de Início”.</p><p>O primeiro acesso precisa de internet; cenários e personagens usados ficam disponíveis no cache enquanto o navegador o mantiver.</p><button>FECHAR</button>';dialog.style.cssText='max-width:420px;padding:25px;background:#20261c;color:#f4edd7;border:1px solid #73834f;font:14px Arial;line-height:1.7';document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.remove();dialog.showModal()}};})();
